using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.FiniteGroups.NikolovSegal;

internal sealed class TransitiveCoverageDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "An independent transitive simple-group value supplier yields exact large-minimal-normal absorption through the actual factor orbits.",
        H("From transitive blocks to conditional absorption"),
        Blocks(
            Describe.Lean(
                DescribeId.Create("nikolov-segal-transitivecoverage-transitivesimplecommutatorsupplier"),
                DeclarationHandle.Create("D5/S3/FiniteGroups/NikolovSegal/TransitiveCoverage.TransitiveSimpleCommutatorSupplier"),
                H("The independent transitive supplier"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Fix natural q, m and C. For every finite nonabelian simple group S with C less than its order, every finite nonempty index type I, and every tuple k of automorphisms of I to S indexed by Fin m, suppose permutations sigma and component automorphisms beta satisfy k(i)(x)(sigma(i)(j)) = beta(i)(j)(x(j)). If the subgroup generated by sigma is transitive, the supplier requires PrescribedCommutatorCoverage(I to S,q,m,k). This means an inner tuple y is chosen before every target t, after which a commutator tuple c may depend on t. This supplier is UNPROVED in this formal development."))),
                DescribeRole.Definition),
            Describe.Lean(
                DescribeId.Create("nikolov-segal-transitivecoverage-uniformtransitivesimplecommutatorsupplier"),
                DeclarationHandle.Create("D5/S3/FiniteGroups/NikolovSegal/TransitiveCoverage.UniformTransitiveSimpleCommutatorSupplier"),
                H("Uniform choice before all groups and tuples"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every positive natural q, there must exist natural m and C with m positive such that TransitiveSimpleCommutatorSupplier(q,m,C) holds. The length and cutoff are chosen before the simple group, index type, factor count and prescribed tuple. This uniform statement is UNPROVED in this formal development."))),
                DescribeRole.Definition),
            Describe.Lean(
                DescribeId.Create("nikolov-segal-transitivecoverage-minimal-normal-coverage-of-transitive-supplier"),
                DeclarationHandle.Create("D5/S3/FiniteGroups/NikolovSegal/TransitiveCoverage.minimal_normal_coverage_of_transitive_supplier"),
                H("Coverage from actual invariant orbits"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Let G be any finite group and N any minimal nontrivial normal subgroup. Fix natural q,m,C and assume TransitiveSimpleCommutatorSupplier(q,m,C), noncommutativity of N, and that every actual minimal normal factor of N is nonabelian simple of order greater than C. Then every prescribed k from Fin m to MulAut(N) satisfies PrescribedCommutatorCoverage(N,q,m,k). The full socle and trivial center follow from minimal normality. The actual orbit product is constructed, and ambient factor conjugacy supplies isomorphisms to a representative simple group on each block. Transport retains the genuine component automorphisms and the exact generated permutation action. The supplier applies on each transitive orbit; equivariance combines their value sets with the same q and exact m."))),
                DescribeRole.Theorem),
            Describe.Lean(
                DescribeId.Create("nikolov-segal-transitivecoverage-absorption-of-transitive-supplier"),
                DeclarationHandle.Create("D5/S3/FiniteGroups/NikolovSegal/TransitiveCoverage.absorption_of_transitive_supplier"),
                H("Exact conditional minimal-normal absorption"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Fix natural q,m,C,cutoff with cutoff at least four and twice C less than cutoff factorial. Under TransitiveSimpleCommutatorSupplier(q,m,C), LargeMinimalNormalAbsorption(q,m,cutoff) holds: for every finite G, minimal nontrivial normal N with alpha(N) greater than cutoff, a in N and x in the exact m-term ordered q-power value set of G, a times x belongs to the same value set. Large-alpha structure supplies the actual large simple factors; block coverage for the corrected automorphisms and the prescribed coset-power identity give the conclusion. The existing generator decomposition consumes precisely this absorption interface."))),
                DescribeRole.Theorem),
            Paragraph(Text("The source is Part I, DOI 10.4007/annals.2007.165.171, printed pages 227\u2013228. The supplier is a centerless simple-group, chosen-length specialization sufficient for this reduction. Published Proposition 10.2 also treats quasisimple groups and every length m at least z(q); its full printed statement is not formalized here. The supplier is unproved in this formal development, not an open research conjecture. Uniform power width, restricted Burnside bounds and unconditional strong completeness remain unproved.")))));
}
